function writeOutputs(outputDir, opts, detector, trajectories, frames, ...
        photonEvents, photophysics, localizationTable, trackTable, ...
        curvature, diffusion)
    import membrane_tracking.curved_miet.*

    writetable(photonEvents, fullfile(outputDir, ...
        'miet_photon_events.csv'));
    writetable(localizationTable, fullfile(outputDir, ...
        'miet_localizations.csv'));
    writetable(trackTable, fullfile(outputDir, ...
        'miet_particle_tracks.csv'));
    writetable(diffusion.msdTable, fullfile(outputDir, ...
        'miet_surface_msd.csv'));

    summary = table(opts.tipHeightUm, curvature.tipHeightUm, ...
        curvature.tipHeightSigmaUm, opts.curvaturePerUm, ...
        curvature.curvaturePerUm, curvature.curvatureSigmaPerUm, ...
        opts.diffusionUm2PerS, diffusion.DMsdCorrectedUm2PerS, ...
        diffusion.DFisherMLEUm2PerS, ...
        diffusion.diffusionFisherSigmaUm2PerS, ...
        diffusion.truthValidation.fullSurfaceLag1DiffusionUm2PerS, ...
        height(localizationTable), diffusion.nTracksUsed, ...
        'VariableNames', {'trueTipHeightUm', 'estimatedTipHeightUm', ...
        'tipHeightSigmaUm', 'trueCurvaturePerUm', ...
        'estimatedCurvaturePerUm', 'curvatureSigmaPerUm', ...
        'trueDiffusionUm2PerS', 'correctedMsdDiffusionUm2PerS', ...
        'fisherMleDiffusionUm2PerS', 'diffusionFisherSigmaUm2PerS', ...
        'sampledTruthDiffusionUm2PerS', 'nLocalizations', 'nTracksUsed'});
    writetable(summary, fullfile(outputDir, ...
        'miet_curvature_diffusion_summary.csv'));

    save(fullfile(outputDir, 'miet_curved_membrane_simulation.mat'), ...
        'opts', 'detector', 'trajectories', 'frames', 'photonEvents', ...
        'photophysics', 'localizationTable', 'trackTable', 'curvature', ...
        'diffusion', '-v7.3');
end
